 {Keyboard r(c,saved.session);r.open(true);r.credentials();r.prompt();r.open();need(r.session.variable(45)==-2,"Submitted reopen normalized V45");r.type(209);r.prompt();need(r.session.count(101)==1,"Empty residual submit altered card");r.end();}
 {Keyboard r(c,saved.session);r.open(true);const int before=r.session.variable(45);auto conflict=key();conflict.buttons[int(InputAction::Cancel)].pressed=true;r.tick(conflict);r.tick();need(r.session.variable(45)==before&&r.pictures.at(4).position.y==4603,"Cancel+Confirm wrote a character");auto opposite=key(InputAction::Up);opposite.buttons[int(InputAction::Down)].pressed=true;r.tick(opposite);r.tick();r.keyId=100;need(r.pictures.at(21).position.x==47&&r.pictures.at(21).position.y==162,"Opposite input moved twice");r.type(100);need(r.pictures.at(4).position.y==4603-27*240,"Prioritized Up failed");for(int target:{0,10,110,208,307,109,209}){r.go(target);if(target==209){need(r.pictures.at(21).transparency==100&&r.pictures.at(22).position.x==255&&r.pictures.at(22).position.y==195&&r.pictures.at(22).transparency==40,"Enter highlight used small cursor");}}r.type(0);r.prompt();r.end();}
 {auto varied=c;for(const auto& [id,xy]:std::vector<std::pair<std::string,Json>>{{p.at("user_label").get<std::string>(),{63,38}},{p.at("enter_cursor").get<std::string>(),{251,191}}}){auto cue=varied.cue(id);cue["position"]["xy"]=xy;varied.setMediaDefinition("cues",id,cue);}Keyboard r(varied,saved.session);r.open(true);r.go(209);need(r.pictures.at(2).position.x==63&&r.pictures.at(2).position.y==38&&r.pictures.at(22).position.x==251&&r.pictures.at(22).position.y==191,"Registration ignored content-owned picture coordinates");r.type(0);r.prompt();r.end();}
 // Every source edge is executed by the public input consumer, including four Enter entrances and two exits.
 {Keyboard r(c,saved.session);r.open(true);for(const auto& [id,neighbors]:p.at("neighbors").items()){for(const auto& [name,target]:neighbors.items()){r.go(std::stoi(id));InputAction a=name=="up"?InputAction::Up:name=="right"?InputAction::Right:name=="left"?InputAction::Left:InputAction::Down;r.press(a);r.keyId=target;const auto xy=p.at("cursor_positions").at(std::to_string(r.keyId));if(r.keyId!=209){need(r.pictures.at(21).position.x==xy[0].get<double>()&&r.pictures.at(21).position.y==xy[1].get<double>(),"Source directional edge failed");}}}r.type(0);r.prompt();r.end();}
 {Keyboard r(c,saved.session);r.open(true);auto held=InputFrame{};held.buttons[int(InputAction::Confirm)].held=true;for(int n=0;n<100;++n){r.tick(held);}need(r.pictures.at(4).position.y==4603,"Held key fabricated triggered input");r.scene.deactivate();auto before=r.session.exportState();for(int n=0;n<100;++n){r.tick(key());}need(r.session.exportState()==before&&!r.session.flag(448)&&r.session.count(101)==0,"Retired keyboard changed current session");}
 {Keyboard r(c,saved.session);r.open(true);for(int k:{102,301,302,102,208,208,200,209,304,2,1,1,9,5,3,8,209}){r.type(k);}need(r.session.count(101)==0&&r.scene.foreground()==ForegroundKind::Content,"Award skipped source result presentation");r.scene.deactivate();auto before=r.session.exportState();for(int n=0;n<500;++n){r.tick(key());}need(r.session.exportState()==before&&r.session.count(101)==0&&!r.session.flag(448)&&r.session.flag(1)&&r.session.flag(18),"Retired result granted a late card");}
 {auto bad=saved;bad.session.inventory[101]=1;bad.session.worldFlags[c.facts.switches.at(447)]=false;rejects([&]{validateSave(c,bad);});bad=saved;bad.session.inventory[101]=2;rejects([&]{validateSave(c,bad);});auto changed=c;changed.catalog["flows"]["registration-consult"]["steps"][2]["options"][0]["steps"][0]["flow"]="m151-e8-p1";rejects([&]{Keyboard r(changed,saved.session);r.open(true);});}
 {auto e=Keyboard::fixture(c,saved.session);e.map=164;e.playerTile={18,9};e.direction=Direction::Right;e.session.inventory[101]=1;GameSession st(c.items,e.session,c.facts);CombatScene sc(c,st,e,safe);InputFrame in;in.movement=Direction::Right;sc.update(in);for(int n=0;n<60;++n){sc.update({});}need(sc.world().player().motion.tile()==TilePosition{19,9}&&sc.foreground()==ForegroundKind::Content&&!st.flag(449)&&st.count(20)==0,"G3 contact handoff fabricated progress");for(int n=0;n<60;++n){sc.update(in);}need(sc.world().player().motion.tile()==TilePosition{19,9},"G3 handoff allowed crossing");bool notice=false;for(const auto& ev:sc.takePresentation()){notice|=ev.kind==PresentationEvent::Kind::Notice&&ev.id.find("G3")!=std::string::npos;}need(notice,"G3 handoff has no clear notice");sc.deactivate();auto before=st.exportState();for(int n=0;n<60;++n){sc.update(key());}need(st.exportState()==before,"Retired G3 handoff changed progress");}
 std::cout<<"G2-06 focused navigation/slots/BS/Esc/residual/input-priority/outer-session/retirement/migration passed\n";
