int main(int argc,char**argv){try{std::cout.setf(std::ios::unitbuf);need(argc==5,"G2-06 package source isolated-root rules|natural|load|no-server");auto c=loadCombatContent(argv[1]);const auto raw=read(argv[2]);const auto saved=decodeSave(c,raw);const std::filesystem::path root=argv[3];std::filesystem::create_directories(root);const std::string mode=argv[4];if(mode=="baseline"){RegistrationDriver run(c,root,"public-inputs-baseline.jsonl");run.game.configureSaveDirectory(root);std::ofstream(root/"slot-01.json")<<raw;run.load(1);run.reception();run.startReception();return 0;}need(c.compatibility=="post-f5-g2-normal-6","Wrong identity");if(mode=="rules"){rules(c,saved,raw);return 0;}RegistrationDriver run(c,root,"public-inputs-"+mode+".jsonl");run.game.configureSaveDirectory(root);if(mode!="load"){std::ofstream(root/"slot-01.json")<<raw;}run.load(mode=="load"?2:1);const auto start=run.game.session().exportState();run.reception();run.startReception();run.choose(0);run.prompt();run.open();run.type(0);run.prompt();run.open();run.type(200);run.type(209);run.type(209);run.prompt();need(run.game.session().count(101)==(mode=="load"?1:0),"Wrong credential changed inventory");run.open();run.credentials();need(run.game.session().count(101)==(mode=="no-server"?0:1),"Natural credential result wrong");run.open();run.credentials();need(run.game.session().count(101)==(mode=="no-server"?0:1),"Natural duplicate changed inventory");run.end();if(mode!="no-server"){run.press(InputAction::Cancel);run.select(0);auto rows=run.game.menuView().rows;auto card=std::find_if(rows.begin(),rows.end(),[](const auto& r){return r.id==101;});need(card!=rows.end()&&!card->enabled,"Card absent or actively usable");run.closeMenu();run.actObject("m159-e5");need(run.game.mapId()==164&&run.game.world().player().motion.tile()==TilePosition{2,9}&&run.game.session().count(101)==1,"M164 west entry consumed card");run.walk({10,9});run.settle();run.actObject("m164-e3");need(run.game.mapId()==159&&run.game.world().player().motion.tile()==TilePosition{23,15},"M164 west return absent");}run.receptionBack();need(run.game.session().hp()==start.hp&&run.game.session().magazine(22)==start.magazines.at(22),"Registration changed health/ammo");if(mode=="natural"){run.monitor(2,true);need(!std::filesystem::exists(root/"slot-02.json"),"Cancelled save wrote");run.monitor(2);SaveFiles disk(c,root);auto final=disk.read(2);need(final.session.saveCount==start.saveCount+1&&final.session.inventory.at(101)==1&&final.scene.map==151,"Registration save lost card/count/map");}std::cout<<"G2-06 "<<mode<<" public ticks="<<run.ticks<<" HP="<<run.game.session().hp()<<" I22="<<run.game.session().magazine(22)<<" I101="<<run.game.session().count(101)<<" saves="<<run.game.session().saveCount()<<" maps="<<Json(run.maps)<<'\n';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
